const native=MethodChannel('familyguard/device');
const endpoint=String.fromEnvironment('API_URL',defaultValue:'https://api.example.invalid');
final apiProvider=Provider((ref)=>Api());
Future<void> startFamilyGuard({required bool child})async{
 WidgetsFlutterBinding.ensureInitialized();
 const key=String.fromEnvironment('FIREBASE_API_KEY');
 bool configured=key.isNotEmpty;
