}
class Api{
 final Dio dio=Dio(BaseOptions(baseUrl:endpoint,connectTimeout:const Duration(seconds:12),receiveTimeout:const Duration(seconds:15)));
 Future<dynamic> call(String method,String path,{Map<String,dynamic>? data,bool child=false})async{
  if(!endpoint.startsWith('https://'))throw StateError('HTTPS API_URL required');
  final raw=data==null?'':jsonEncode(data);final url='/api/v1$path';Map<String,dynamic> headers={'Content-Type':'application/json'};
  if(child){headers.addAll(Map<String,dynamic>.from(await native.invokeMethod('sign',{'method':method,'path':url,'body':raw}) as Map));}
  else{final token=await FirebaseAuth.instance.currentUser?.getIdToken();if(token==null)throw StateError('Sign in first');headers['Authorization']='Bearer $token';}
  return (await dio.request(url,data:data==null?null:raw,options:Options(method:method,headers:headers))).data;
 }
 Future<dynamic> publicCall(String method,String path,{Map<String,dynamic>? data})async=>(await dio.request('/api/v1$path',data:data,options:Options(method:method))).data;
}
